563	  async function hasActiveCheckoutManagementOverride(
564	    actorAgentId: string,
565	    companyId: string,
566	    assigneeAgentId: string,
567	  ) {
568	    const allowedByGrant = await access.hasPermission(
569	      companyId,
570	      "agent",
571	      actorAgentId,
572	      "tasks:manage_active_checkouts",
573	    );
574	    if (allowedByGrant) return true;
575	
576	    const companyAgents = await agentsSvc.list(companyId);
577	    const agentsById = new Map(companyAgents.map((agent) => [agent.id, agent]));
578	    const actorAgent = agentsById.get(actorAgentId);
579	    if (!actorAgent) return false;
580	    if (canCreateAgentsLegacy(actorAgent)) return true;
581	
582	    // Reporting-chain managers may intervene in an agent's active checkout
583	    // without taking the task over. Peers must own the checkout/run first.
584	    let cursor: string | null = assigneeAgentId;
585	    for (let depth = 0; cursor && depth < 50; depth += 1) {
586	      const assignee = agentsById.get(cursor);
587	      if (!assignee) return false;
588	      if (assignee.reportsTo === actorAgentId) return true;
589	      cursor = assignee.reportsTo;
590	    }
591	
592	    return false;
593	  }
