595	  async function assertAgentIssueMutationAllowed(
596	    req: Request,
597	    res: Response,
598	    issue: { id: string; companyId: string; status: string; assigneeAgentId: string | null },
599	  ) {
600	    if (req.actor.type !== "agent") return true;
601	    const actorAgentId = req.actor.agentId;
602	    if (!actorAgentId) {
603	      res.status(403).json({ error: "Agent authentication required" });
604	      return false;
605	    }
606	    if (issue.assigneeAgentId === null) {
607	      return true;
608	    }
609	    if (issue.assigneeAgentId !== actorAgentId) {
610	      if (await hasActiveCheckoutManagementOverride(actorAgentId, issue.companyId, issue.assigneeAgentId)) {
611	        return true;
612	      }
613	      if (issue.status === "in_progress") {
614	        res.status(409).json({
615	          error: "Issue is checked out by another agent",
616	          details: {
617	            issueId: issue.id,
618	            assigneeAgentId: issue.assigneeAgentId,
619	            actorAgentId,
620	          },
621	        });
622	      } else {
623	        res.status(403).json({
624	          error: "Agent cannot mutate another agent's issue",
625	          details: {
626	            issueId: issue.id,
627	            assigneeAgentId: issue.assigneeAgentId,
628	            actorAgentId,
629	            status: issue.status,
630	            securityPrinciples: ["Least Privilege", "Complete Mediation", "Fail Securely"],
631	          },
632	        });
633	      }
634	      return false;
635	    }
636	    if (issue.status !== "in_progress") {
637	      return true;
638	    }
639	    const runId = requireAgentRunId(req, res);
640	    if (!runId) return false;
641	    const ownership = await svc.assertCheckoutOwner(issue.id, actorAgentId, runId);
642	    if (ownership.adoptedFromRunId) {
643	      const actor = getActorInfo(req);
644	      await logActivity(db, {
645	        companyId: issue.companyId,
646	        actorType: actor.actorType,
647	        actorId: actor.actorId,
648	        agentId: actor.agentId,
649	        runId: actor.runId,
650	        action: "issue.checkout_lock_adopted",
651	        entityType: "issue",
652	        entityId: issue.id,
653	        details: {
654	          previousCheckoutRunId: ownership.adoptedFromRunId,
655	          checkoutRunId: runId,
656	          reason: "stale_checkout_run",
657	        },
658	      });
659	    }
660	    return true;
661	  }
