707	            issueId: issue.id,
708	            unresolvedBlockerIssueIds: readiness.unresolvedBlockerIssueIds,
709	          },
710	        });
711	        return false;
712	      }
713	    }
714	
715	    if (req.actor.type !== "agent") return true;
716	
717	    const actorAgentId = req.actor.agentId;
718	    if (!actorAgentId) {
719	      res.status(403).json({ error: "Agent authentication required" });
